import java.util.*;

class Solution {
    public int findCheapestPrice(int n, int[][] flights, int src, int dst, int k) {
        int[] dist = new int[n];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[src] = 0;
        for (int i = 0; i <= k; i++) {
            int[] temp = Arrays.copyOf(dist, n);
            for (int[] f : flights) {
                if (dist[f[0]] != Integer.MAX_VALUE) {
                    temp[f[1]] = Math.min(temp[f[1]], dist[f[0]] + f[2]);
                }
            }
            dist = temp;
        }
        return dist[dst] == Integer.MAX_VALUE ? -1 : dist[dst];
    }
}

import java.util.*;

class Solution {
    public int findCheapestPrice(int n, int[][] flights, int src, int dst, int k) {
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] f : flights) adj.get(f[0]).add(new int[]{f[1], f[2]});
        int[] best = new int[n];
        Arrays.fill(best, Integer.MAX_VALUE);
        best[src] = 0;
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{src, 0});
        int stops = 0;
        while (!queue.isEmpty() && stops <= k) {
            int size = queue.size();
            int[] curBest = Arrays.copyOf(best, n);
            for (int i = 0; i < size; i++) {
                int[] cur = queue.poll();
                int node = cur[0], cost = cur[1];
                for (int[] next : adj.get(node)) {
                    int newCost = cost + next[1];
                    if (newCost < curBest[next[0]]) {
                        curBest[next[0]] = newCost;
                        queue.offer(new int[]{next[0], newCost});
                    }
                }
            }
            best = curBest;
            stops++;
        }
        return best[dst] == Integer.MAX_VALUE ? -1 : best[dst];
    }
}
